def create_numeric_variation(question_text, values_dict, multipliers=None, new_values=None):
    """Create numeric variations: change percentages, numbers, ratios"""
    if new_values is None:
        new_values = {}
    q = question_text
    for old_val, new_val in new_values.items():
        q = q.replace(str(old_val), str(new_val))
    return q

def create_context_variation(question_text, domain_map):
    """Create context variations: change domain/system type"""
    q = question_text
    for old_domain, new_domain in domain_map.items():
        q = q.replace(old_domain, new_domain)
    return q

def create_scenario_variation(question_text, scenario_map):
    """Create scenario variations: change region/time/scale"""
    q = question_text
    for old_scenario, new_scenario in scenario_map.items():
        q = q.replace(old_scenario, new_scenario)
    return q

